head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > fixedColumnScrollHidden]<br/>fixedColumn 속성으로 고정된 Column 하단의 가로 스크롤 영역에 스크롤 버튼을 숨길지 설정합니다.",
    "validation" : [
        "미설정 또는 false 설정 시 고정된 Column 하단의 가로 스크롤 영역에 스크롤 버튼을 표시합니다.",
        "true 설정 시 고정된 Column 하단의 가로 스크롤 영역에 스크롤바와 스크롤 버튼을 표시하지 않습니다.",
        "true 설정 시 가로 스크롤 영역은 유지되며 스크롤바와 스크롤 버튼이 표시되지 않습니다.",
        "fixedColumn, rowNumVisible, rowStatusVisible 속성으로 고정된 왼쪽 Column 영역의 하단 스크롤 영역에 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }    

    // 조건 설정   
    let properties = {
        fixedColumnScrollHidden: con_fixedColumnScrollHidden.getText(),
        fixedColumn: 2,
        dataList: "data:dlt_bind",      
        rowStatusVisible: true,
        rowNumVisible: true,
    };

    let cList = $c.gcm.createCList(properties);      
    // let eList = $c.gcm.createEList([]) 

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');  
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:350px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column5" value="name5"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col5" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';    

    // target 생성
    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    scwin.btn_fixedColumnScrollHidden_onclick();
}



scwin.btn_fixedColumnScrollHidden_onclick = function (e) {
    let targetElement = document.querySelector('td[id*="target1_scrollX_left"]');
    let targetDiv = targetElement.querySelector('div');

    if (targetDiv) {        
        let overflowX = window.getComputedStyle(targetDiv).overflowX;        

        wf_body_bottom.getObj("scwin").setReturnValue("overflow-x: " + overflowX);
    }
};
